'use client';

import React, { useState } from 'react';
import { useParams } from 'next/navigation';
import { contactService } from '@/src/services/contact.service';
import { ContactFormData } from '@/src/types/contact.types';
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
import { useToast } from "@/src/components/ui/use-toast";

interface ContactFormProps {
    subjects: string[];
    submitButtonText: string;
}

export default function ContactForm({ subjects, submitButtonText }: ContactFormProps) {
    const params = useParams();
    const locale = (params?.locale as string) || 'tr';
    const { toast } = useToast();
    const [loading, setLoading] = useState(false);

    const [formData, setFormData] = useState<ContactFormData>({
        name: '',
        email: '',
        subject: '',
        message: '',
        locale: locale,
    });

    const [errors, setErrors] = useState<Partial<Record<keyof ContactFormData, string>>>({});

    const validateForm = (): boolean => {
        const newErrors: Partial<Record<keyof ContactFormData, string>> = {};

        if (!formData.name?.trim()) {
            newErrors.name = 'Lütfen adınızı ve soyadınızı girin';
        }

        if (!formData.email?.trim()) {
            newErrors.email = 'Lütfen e-posta adresinizi girin';
        } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email)) {
            newErrors.email = 'Geçerli bir e-posta adresi girin';
        }

        if (!formData.subject?.trim()) {
            newErrors.subject = 'Lütfen bir konu seçin';
        }

        if (!formData.message?.trim()) {
            newErrors.message = 'Lütfen mesajınızı girin';
        }

        setErrors(newErrors);
        return Object.keys(newErrors).length === 0;
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();

        if (!validateForm()) {
            return;
        }

        setLoading(true);
        try {
            const response = await contactService.submitContactForm({
                ...formData,
                locale,
            });

            toast({
                title: '✅ Başarılı',
                description: response.message || 'Mesajınız başarıyla gönderildi!',
            });

            setFormData({
                name: '',
                email: '',
                subject: '',
                message: '',
                locale: locale,
            });
            setErrors({});
        } catch (error: any) {
            toast({
                title: '❌ Hata',
                description: error?.message || 'Bir hata oluştu. Lütfen tekrar deneyin.',
                variant: 'destructive',
            });
        } finally {
            setLoading(false);
        }
    };

    const handleChange = (field: keyof ContactFormData, value: string) => {
        setFormData({ ...formData, [field]: value });
        if (errors[field]) {
            setErrors({ ...errors, [field]: undefined });
        }
    };

    return (
        <form onSubmit={handleSubmit}>
            <div className="px-4 sm:px-6 md:px-10 lg:px-16 xl:px-20 max-w-7xl mx-auto">
                <div className="flex flex-col md:flex-row md:gap-4">
                    <div className="!flex-1">
                        <Label htmlFor="name">
                            <div className="flex items-center">
                                <p className="text-[14px] leading-5 text-[#474D66]">Ad - Soyad</p>
                                <span className="text-red-500 ml-[2px]">*</span>
                            </div>
                        </Label>
                        <Input
                            id="name"
                            placeholder="Lütfen Ad - Soyad giriniz"
                            className="!h-[48px] !rounded-md"
                            value={formData.name}
                            onChange={(e) => handleChange('name', e.target.value)}
                        />
                        {errors.name && (
                            <p className="text-sm text-red-500 mt-1">{errors.name}</p>
                        )}
                    </div>

                    <div className="!flex-1">
                        <Label htmlFor="email">
                            <div className="flex items-center">
                                <p className="text-[14px] leading-5 text-[#474D66]">E-posta</p>
                                <span className="text-red-500 ml-[2px]">*</span>
                            </div>
                        </Label>
                        <Input
                            id="email"
                            type="email"
                            placeholder="Lütfen E-posta giriniz"
                            className="!h-[48px] !rounded-md"
                            value={formData.email}
                            onChange={(e) => handleChange('email', e.target.value)}
                        />
                        {errors.email && (
                            <p className="text-sm text-red-500 mt-1">{errors.email}</p>
                        )}
                    </div>
                </div>

                <div>
                    <Label htmlFor="subject">
                        <div className="flex items-center">
                            <p className="text-[14px] leading-5 text-[#474D66]">Konu</p>
                            <span className="text-red-500 ml-[2px]">*</span>
                        </div>
                    </Label>
                    <Select
                        value={formData.subject}
                        onValueChange={(value) => handleChange('subject', value)}
                    >
                        <SelectTrigger className="!h-[48px]">
                            <SelectValue placeholder="Lütfen bir konu seçin" />
                        </SelectTrigger>
                        <SelectContent>
                            {subjects.map((subject) => (
                                <SelectItem key={subject} value={subject}>
                                    {subject}
                                </SelectItem>
                            ))}
                        </SelectContent>
                    </Select>
                    {errors.subject && (
                        <p className="text-sm text-red-500 mt-1">{errors.subject}</p>
                    )}
                </div>

                <div>
                    <Label htmlFor="message">
                        <div className="flex items-center">
                            <p className="text-[14px] leading-5 text-[#474D66]">Mesaj</p>
                            <span className="text-red-500 ml-[2px]">*</span>
                        </div>
                    </Label>
                    <Textarea
                        id="message"
                        placeholder="Lütfen mesajınızı giriniz"
                        className="!rounded-md"
                        rows={6}
                        maxLength={1000}
                        value={formData.message}
                        onChange={(e) => handleChange('message', e.target.value)}
                    />
                    <div className="flex justify-between items-center mt-1">
                        {errors.message && (
                            <p className="text-sm text-red-500">{errors.message}</p>
                        )}
                        <p className="text-xs text-gray-500 ml-auto">
                            {formData.message.length} / 1000
                        </p>
                    </div>
                </div>

                <div className="flex justify-center">
                    <Button
                        type="submit"
                        disabled={loading}
                        className={`
                            bg-primary-pink
                            text-white
                            hover-bg-primary-blue
                            px-5 md:px-8 py-2 md:py-4
                            rounded-full
                            cursor-pointer
                            transition-colors duration-300 ease-in
                            flex items-center justify-center gap-2 h-auto
                            border-none
                        `}
                    >
                        <p className="text-sm md:text-base capitalize font-medium">
                            {submitButtonText}
                        </p>
                    </Button>
                </div>
            </div>
        </form>
    );
}